    for f in os.listdir(dp):
        n=int(re.search(r'(\d{3})_', f).group(1))
        num2path[n]=os.path.join(dp,f)

def parse_file(n):
    fp = num2path[n]
    ext = fp.rsplit('.',1)[-1].lower()
    meta = {}
    if ext == 'csv':
        with open(fp,'r',encoding='utf-8') as fh:
            rows = list(csv.DictReader(fh))
        for r in rows:
            if r.get('row_type')=='metadata':
                meta[r['key']] = r['value']
    elif ext == 'json':
        with open(fp,'r',encoding='utf-8') as fh:
            j = json.load(fh)
        for k in ['portfolio_key','immutable_entity_key','referenced_revision','current_revision','evidence_role','subject','custodian','reviewer','source_system','matter_number','record_id']:
            if k in j: meta[k]=j[k]
    elif ext == 'xml':
        with open(fp,'r',encoding='utf-8') as fh:
            root = ET.fromstring(fh.read())
        tagmap = {'record-id':'record_id','matter-number':'matter_number','portfolio-key':'portfolio_key',
                  'source-system':'source_system','evidence-role':'evidence_role','immutable-entity-key':'immutable_entity_key',
                  'referenced-revision':'referenced_revision','current-revision':'current_revision'}
        for ch in root:
            t = ch.tag
            if t in tagmap: meta[tagmap[t]] = (ch.text or '').strip()
    elif ext == 'eml':
        with open(fp,'rb') as fh:
            msg = BytesParser(policy=policy.default).parse(fh)
        body = msg.get_body(preferencelist=('plain',)).get_content()
        meta['_body'] = body
        # headers
        meta['portfolio_key'] = msg.get('X-Portfolio-Key')
        meta['matter_number'] = msg.get('X-Matter-Number')
        meta['source_system'] = msg.get('X-Source-System')
    else:
        with open(fp,'r',encoding='utf-8',errors='replace') as fh:
            txt = fh.read()
        meta['_body'] = txt
        # md table / txt key:value
        for label, key in [('Portfolio key','portfolio_key'),('Immutable entity','immutable_entity_key'),
                           ('Referenced revision','referenced_revision'),('Current revision','current_revision'),
                           ('Evidence role','evidence_role'),('Custodian','custodian'),('Reviewer','reviewer'),
                           ('Matter','matter_number'),('Subject','subject'),('Source system','source_system')]:
            m = re.search(label + r'[^\n|]*?([A-Za-z0-9_.\- ]+?)(?:\n|\||$)', txt)
    return meta, ext

# parse all, print referenced vs current per key
print("Key | file -> referenced_revision vs current_revision")
for k in range(1,13):
    files = [k, k+12, k+24, k+36, k+48, k+60, k+72, k+84]
    pairs = []
    for n in files:
        try:
            meta, ext = parse_file(n)
        except Exception as e:
            pairs.append(f"[{n} ERR]"); continue
        rr = meta.get('referenced_revision'); cr = meta.get('current_revision')
        ent = meta.get('immutable_entity_key'); pk = meta.get('portfolio_key')
        pairs.append(f"{n}:pk={pk},ent={ent},ref={rr},cur={cr}")
    print(f"CBP-061-{k:02d} :: " + " | ".join(pairs))
"}

